using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using CreatorSettlement;
[assembly:System.Runtime.Versioning.TargetFramework(".NETFramework,Version=v4.8")]
public static class TestsEditing {
 static int passed;static string dir;static readonly BindingFlags FI=BindingFlags.Instance|BindingFlags.NonPublic;
 [DllImport("user32.dll")] static extern IntPtr GetThreadDpiAwarenessContext();
 [DllImport("user32.dll")] static extern bool AreDpiAwarenessContextsEqual(IntPtr a,IntPtr b);
 static void Assert(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 static object Field(object x,string n){return x.GetType().GetField(n,FI).GetValue(x);}
 static void Call(object x,string n,params object[] a){x.GetType().GetMethod(n,FI).Invoke(x,a);Application.DoEvents();}
 static IEnumerable<Control> Children(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in Children(x))yield return y;}}
 static void Dialog(MainWindow f,string action,Dictionary<string,string> fields,bool cancel=false){using(var timer=new Timer{Interval=40}){timer.Tick+=(o,e)=>{var form=Application.OpenForms.OfType<TableRowEditor>().FirstOrDefault();if(form==null)return;timer.Stop();form.Opacity=0;var inputs=(Dictionary<DataColumn,TextBox>)Field(form,"inputs");foreach(var pair in fields)inputs.Single(x=>x.Key.ColumnName==pair.Key).Value.Text=pair.Value;if(cancel){form.DialogResult=DialogResult.Cancel;form.Close();}else Children(form).OfType<Button>().Single(b=>b.Text=="保存这一行").PerformClick();};timer.Start();Call(f,action);}}
 static string Copy(DataGridView g,int row,string col){g.CurrentCell=g.Rows[row].Cells[col];g.ClearSelection();g.CurrentCell.Selected=true;return GridCopy.SelectionText(g);}
 static void Shot(Form f,string name){using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(dir,name));}}
 [STAThread] public static int Main(string[] args){try{dir=args[0];CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;Application.EnableVisualStyles();using(var f=new MainWindow()){f.ShowInTaskbar=false;f.Opacity=0;f.Show();Assert(AreDpiAwarenessContextsEqual(GetThreadDpiAwarenessContext(),new IntPtr(-4)),"native PerMonitorV2 awareness active");var sheets=new List<Sheet>{(Sheet)typeof(TestsV13).GetMethod("Input",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null)};typeof(MainWindow).GetField("sheets",FI).SetValue(f,sheets);var choice=(ComboBox)Field(f,"sheetChoice");typeof(MainWindow).GetField("busy",FI).SetValue(f,true);choice.Items.Add("演示");choice.SelectedIndex=0;typeof(MainWindow).GetField("busy",FI).SetValue(f,false);Call(f,"LoadSelected");var m=(Model)Field(f,"model");var grids=new[]{(DataGridView)Field(f,"checkGrid"),(DataGridView)Field(f,"payGrid"),(DataGridView)Field(f,"warningGrid"),(DataGridView)Field(f,"adjustGrid")};for(int i=0;i<4;i++){Call(f,"Navigate",i);var g=grids[i];Assert(g.SelectionMode==DataGridViewSelectionMode.CellSelect&&g.MultiSelect&&g.ClipboardCopyMode==DataGridViewClipboardCopyMode.EnableWithoutHeaderText,"cell drag selection and no-header copying table "+i);string col=i==0?"任务/方案ID":"任务ID";Assert(Copy(g,0,col).StartsWith("T"),"single task ID copy table "+i);Assert(g.ContextMenuStrip.Items.Count>=2,"right click copying available table "+i);}
  Call(f,"Navigate",0);var check=grids[0];check.ClearSelection();check.Rows[0].Cells[1].Selected=true;check.Rows[1].Cells[1].Selected=true;Assert(GridCopy.SelectionText(check)=="T1\r\nT1","multiple IDs copy without other columns");GridCopy.SelectRightClick(check,0,1);Assert(check.SelectedCells.Count==2,"right click selected cell keeps range");GridCopy.SelectRightClick(check,2,1);Assert(check.SelectedCells.Count==1&&GridCopy.SelectionText(check)=="T2","right click outside range selects intended cell");check.CurrentCell=check.Rows[0].Cells[1];var filter=(GridFilter)Field(f,"checkFilter");filter.SelectValues("任务/方案ID",new[]{"T1"});check.CurrentCell=check.Rows[0].Cells[1];Assert(GridCopy.ColumnText(check)=="T1\r\nT1","copy column respects current filters");filter.Clear();m.Check.Rows[0][1]="124535749102813721";Assert(Copy(check,0,"任务/方案ID")=="124535749102813721","long ID exact text copied");m.Check.Rows[0][1]="T1";
  int old=m.Check.Rows.Count;Dialog(f,"AddTableRow",new Dictionary<string,string>{{"任务/方案ID","NEW"},{"方案名","手工方案"},{"转化数","2"},{"单价","29"},{"一口价（无手续费）","999"}});Assert(m.Check.Rows.Count==old+1&&(decimal)m.Check.Rows[old][6]==58m&&(decimal)m.Check.Rows[old][8]==-941m,"add check row calculates amount and negative settlement");Call(f,"Undo");Assert(m.Check.Rows.Count==old,"undo add row");Call(f,"Redo");Assert(m.Check.Rows.Count==old+1,"redo add row");Dialog(f,"AddTableRow",new Dictionary<string,string>(),true);Assert(m.Check.Rows.Count==old+1,"cancel adds no row");check.CurrentCell=check.Rows[old].Cells[1];check.ClearSelection();check.CurrentCell.Selected=true;Dialog(f,"EditTableRow",new Dictionary<string,string>{{"单价","30"},{"方案名","改后方案"}});Assert((decimal)m.Check.Rows[old][6]==60m&&Model.Val(m.Check.Rows[old],"方案名")=="改后方案","row editor updates and recalculates");m.ExportCheck(Path.Combine(dir,"added-check.xlsx"));Call(f,"SyncAdjustment");Assert(m.Adjust.AsEnumerable().Any(r=>Model.Val(r,"任务ID")=="NEW"&&(decimal)r[4]==999m),"new manual task syncs fixed cost");
  Call(f,"Navigate",0);check.ClearSelection();check.Rows[old].Cells[1].Selected=true;check.Rows[2].Cells[1].Selected=true;Call(f,"DeleteTableRows");Assert(m.Check.Rows.Count==old-1,"delete selected rows only");Call(f,"Undo");Assert(m.Check.Rows.Count==old+1&&Model.Val(m.Check.Rows[old],"任务/方案ID")=="NEW","undo delete restores original rows and IDs");Call(f,"Redo");Assert(m.Check.Rows.Count==old-1,"redo delete rows");Call(f,"Undo");
  Call(f,"Navigate",1);old=m.Payment.Rows.Count;Dialog(f,"AddTableRow",new Dictionary<string,string>{{"任务ID","MANUAL"},{"任务名称","补录打款"},{"类型(必填)","星视频"}});Assert(m.Payment.Rows.Count==old+1&&Model.Val(m.Payment.Rows[old],"收款类型(必填)")=="小额"&&Model.Val(m.Payment.Rows[old],"打款对象类型(必填)")=="团长","add payment row retains defaults");m.UseReceipt(new Receipt{Channel="银行卡",Name="演示姓名",Phone="13800008000",Identity="110101199001010010",Account="6222000000000001"},"团长");Assert(m.Payment.AsEnumerable().Any(r=>Model.Val(r,"任务ID")=="MANUAL"&&Model.Val(r,"姓名(必填)")=="演示姓名"),"new payment task can reuse receipt");m.ExportPayment(Path.Combine(dir,"manual-payment.xlsx"));
  Call(f,"Navigate",2);old=m.Warnings.Rows.Count;Dialog(f,"AddTableRow",new Dictionary<string,string>{{"任务ID","MANUAL"},{"异常类型","人工说明"},{"说明","补充备注"}});Assert(m.Warnings.Rows.Count==old+1,"add warning row");Call(f,"Undo");Assert(m.Warnings.Rows.Count==old,"warning row undo supported");Call(f,"Redo");Assert(m.Warnings.Rows.Count==old+1,"warning row redo supported");
  Call(f,"Navigate",3);old=m.Adjust.Rows.Count;Dialog(f,"AddTableRow",new Dictionary<string,string>{{"任务ID","ADDADJUST"},{"聚星任务名","补录调差"},{"线上成本","-123.45"},{"备注","人工补充"}});Assert(m.Adjust.Rows.Count==old+1&&(decimal)m.Adjust.Rows[old][4]==-123.45m,"add manual adjustment with negative decimal");var adjust=grids[3];adjust.CurrentCell=adjust.Rows[old].Cells[3];adjust.ClearSelection();adjust.CurrentCell.Selected=true;Call(f,"DeleteTableRows");Assert(m.Adjust.Rows.Count==old,"delete adjustment row");Call(f,"Undo");Assert(m.Adjust.Rows.Count==old+1,"undo adjustment deletion");m.ExportAdjust(Path.Combine(dir,"added-adjust.xlsx"));Assert(File.Exists(Path.Combine(dir,"added-adjust.xlsx")),"edited adjustment exports");
  Shot(f,"ui-edit-copy-100.png");Console.WriteLine("NATIVE_DPI="+f.DeviceDpi);float to125=120f/f.DeviceDpi;f.Scale(new SizeF(to125,to125));Call(f,"FitScreen");Application.DoEvents();Shot(f,"ui-layout-125.png");Assert(f.Width<=Screen.FromControl(f).WorkingArea.Width&&f.Height<=Screen.FromControl(f).WorkingArea.Height,"125 percent simulated layout fits screen");Assert(Rectangle.Intersect(f.RectangleToScreen(f.ClientRectangle),adjust.RectangleToScreen(adjust.ClientRectangle)).Height>=f.ClientSize.Height*0.55,"125 percent editor gets majority of height");f.Scale(new SizeF(1.2f,1.2f));Call(f,"FitScreen");Application.DoEvents();Shot(f,"ui-layout-150.png");Assert(f.Width<=Screen.FromControl(f).WorkingArea.Width&&f.Height<=Screen.FromControl(f).WorkingArea.Height,"150 percent simulated layout fits screen");Assert(Rectangle.Intersect(f.RectangleToScreen(f.ClientRectangle),adjust.RectangleToScreen(adjust.ClientRectangle)).Height>=f.ClientSize.Height*0.55,"150 percent editor gets majority of height");f.Hide();}
  using(var g=new DataGridView()){var table=new DataTable();table.Columns.Add("任务ID");table.Rows.Add("ONLY");g.DataSource=table;using(var owner=new Form()){owner.Controls.Add(g);owner.Show();string copied=null;GridCopy.Attach(g,text=>copied=text,action=>action());g.CurrentCell=g.Rows[0].Cells[0];g.ClearSelection();g.CurrentCell.Selected=true;((ToolStripMenuItem)g.ContextMenuStrip.Items[0]).PerformClick();Assert(copied=="ONLY","right click copy routes exact selection");((ToolStripMenuItem)g.ContextMenuStrip.Items[1]).PerformClick();Assert(copied=="ONLY","right click column routes exact text");owner.Hide();}}
  Console.WriteLine("TOTAL "+passed+" copy editing and DPI assertions passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
